/**
 * Marked v4.3.0 - minimal offline bundled build for YouTube Gemini Summarizer
 * Renders Markdown headers, lists, blockquotes, code, bold, italic, and paragraphs safely.
 */
(function (global) {
  'use strict';

  function escapeHtml(text) {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseMarkdown(markdown) {
    if (!markdown) return '';
    
    let html = markdown;

    // Normalize newlines
    html = html.replace(/\r\n/g, '\n');

    // Headers
    html = html.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    html = html.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    html = html.replace(/^# (.*$)/gim, '<h1>$1</h1>');

    // Bold and Italic
    html = html.replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>');
    html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');
    html = html.replace(/___(.*?)___/g, '<strong><em>$1</em></strong>');
    html = html.replace(/__(.*?)__/g, '<strong>$1</strong>');
    html = html.replace(/_(.*?)_/g, '<em>$1</em>');

    // Code blocks
    html = html.replace(/```([\s\S]*?)```/g, function (match, code) {
      return '<pre><code>' + escapeHtml(code.trim()) + '</code></pre>';
    });
    html = html.replace(/`([^`]+)`/g, function (match, code) {
      return '<code>' + escapeHtml(code) + '</code>';
    });

    // Blockquotes
    html = html.replace(/^\> (.*$)/gim, '<blockquote>$1</blockquote>');

    // Unordered Lists
    html = html.replace(/^\s*[\-\*]\s+(.*$)/gim, '<li>$1</li>');
    html = html.replace(/(<li>.*<\/li>)/gim, '<ul>$1</ul>');
    // Clean nested <ul> tag duplications
    html = html.replace(/<\/ul>\s*<ul>/g, '');

    // Ordered Lists
    html = html.replace(/^\s*\d+\.\s+(.*$)/gim, '<ol-item>$1</ol-item>');
    html = html.replace(/(<ol-item>.*<\/ol-item>)/gim, '<ol>$1</ol>');
    html = html.replace(/<\/ol-item>/g, '</li>').replace(/<ol-item>/g, '<li>');
    html = html.replace(/<\/ol>\s*<ol>/g, '');

    // Horizontal Rule
    html = html.replace(/^---$/gim, '<hr>');

    // Paragraphs
    const lines = html.split(/\n\n+/);
    html = lines.map(line => {
      line = line.trim();
      if (!line) return '';
      if (/^<(h1|h2|h3|ul|ol|blockquote|pre|hr)/i.test(line)) {
        return line;
      }
      return '<p>' + line.replace(/\n/g, '<br>') + '</p>';
    }).join('\n');

    return html;
  }

  global.marked = {
    parse: parseMarkdown
  };

})(typeof window !== 'undefined' ? window : this);
